def _ks(key, n):
    s = bytearray()
    c = 0
    while len(s) < n:
        s.extend(hashlib.sha256(key + struct.pack('>Q', c)).digest())
        c += 1
    return bytes(s[:n])

def _decrypt(pw):
    b = base64.b64decode(_BLOB)
    salt, enc = b[:32], b[32:]
    mk = hashlib.pbkdf2_hmac('sha256', pw.encode(), salt, _ITERATIONS)
    if hashlib.sha256(mk).hexdigest() != _VERIFY:
        return None
    return json.loads(zlib.decompress(bytes(a^b for a,b in zip(enc, _ks(mk, len(enc))))))

def expand(tgt, pw):
    print("Verifying password and decrypting...")
    f = _decrypt(pw)
    if f is None:
        print("ERROR: Wrong password."); return False
    tgt = os.path.abspath(tgt)
    print(f"Extracting {len(f)} files to: {tgt}")
    print()
    dirs = set()
    for rp, b64 in sorted(f.items()):
        fp = os.path.join(tgt, rp)
        d = os.path.dirname(fp)
        if d and d not in dirs:
            os.makedirs(d, exist_ok=True); dirs.add(d)
        with open(fp, "wb") as fh:
            fh.write(base64.b64decode(b64))
        print(f"  {rp}")
    print()
    print(f"Done. {len(f)} files extracted to {tgt}")
    print()
    print("Next steps:")
    print(f"  cd {tgt}")
    print("  python setup_validation_suite.py")
    return True

def main():
    ap = argparse.ArgumentParser(description="Extract Fluent Validation Suite (password protected).")
    ap.add_argument("--target", "-t", default="fluent_validation_suite")
    ap.add_argument("--password", "-p", default=None)
    a = ap.parse_args()
    if os.path.exists(a.target) and os.listdir(a.target):
        print(f"WARNING: {a.target} exists and is not empty.")
        if input("Overwrite? [y/N] ").strip().lower() != "y":
            print("Aborted."); sys.exit(1)
    pw = a.password
    if not pw:
        try:
            import getpass; pw = getpass.getpass("Password: ")
        except Exception:
            pw = input("Password: ")
    if not expand(a.target, pw): sys.exit(1)

if __name__ == "__main__":
    main()
